//! RapidRAW Web core.
//!
//! This crate compiles RapidRAW's image-processing Rust code to WebAssembly so the
//! browser build produces the same results as the desktop app:
//!
//! * RAW development (rawler + RapidRAW's `raw_processing.rs`, included verbatim)
//! * JSON adjustments -> GPU uniform buffer packing (`get_all_adjustments_from_json`)
//! * Mask bitmap generation, histogram/waveform analytics, auto adjustments
//!
//! Modules under `upstream/` are generated by `extract.py` from `src-tauri/src`;
//! the remaining desktop modules are included directly with `#[path]`.

#![allow(clippy::all)]

// ---- RapidRAW desktop modules, reused verbatim -----------------------------
#[path = "../../../src-tauri/src/baseline_exposure.rs"]
pub mod baseline_exposure;
#[path = "../../../src-tauri/src/highlight_reconstruction.rs"]
pub mod highlight_reconstruction;
#[path = "../../../src-tauri/src/multi_exposure.rs"]
pub mod multi_exposure;
#[path = "../../../src-tauri/src/raw_processing.rs"]
pub mod raw_processing;
#[path = "../../../src-tauri/src/white_balance.rs"]
pub mod white_balance;
#[path = "../../../src-tauri/src/formats.rs"]
pub mod formats;

// ---- Items extracted from desktop modules that also contain Tauri glue -----
#[path = "upstream/as_shot.rs"]
pub mod as_shot;
#[path = "upstream/image_processing.rs"]
pub mod image_processing;
#[path = "upstream/mask_generation.rs"]
pub mod mask_generation;
#[path = "upstream/negative_conversion.rs"]
pub mod negative_conversion;
#[path = "upstream/exif_processing.rs"]
pub mod exif_processing;

// ---- Small stand-ins for desktop-only types ---------------------------------
pub mod app_settings;
pub mod shims;

mod api;
pub use api::*;

/// Full desktop settings schema + defaults (used to seed the web settings store).
#[path = "upstream/desktop_settings.rs"]
pub mod desktop_settings;
#[path = "upstream/immich_config.rs"]
mod immich_config;
pub mod immich {
    pub use crate::immich_config::ImmichSettings;
}
